// ***************
// Filename: gpio_regs_if.sv
// Author: FPGA Cores 4 U
// Description: Register interface of gpio: joins the register map gpio_regs
//   (modport regs) and the logic gpio (modport core). cfg_* go from the
//   register map to the logic (register values, _wr write pulses, _rd read
//   pulses), sts_* come back (values read, _set / _clr hardware set / clear
//   pulses). A logic block ties every sts_* member it does not use to 0.
//   Generated by ip/scripts/regmap_gen.py from gpio_regs.json: edit the JSON
//   and regenerate.
// Date: 2026-10-16
interface gpio_regs_if #(
  parameter int WIDTH = 16
) ();
  logic [WIDTH-1:0] sts_out;
  logic [WIDTH-1:0] cfg_out;
  logic cfg_out_wr;
  logic [WIDTH-1:0] cfg_dir;
  logic cfg_dir_wr;
  logic [WIDTH-1:0] sts_in;
  logic [WIDTH-1:0] cfg_set;
  logic cfg_set_wr;
  logic [WIDTH-1:0] cfg_clear;
  logic cfg_clear_wr;
  logic [WIDTH-1:0] cfg_toggle;
  logic cfg_toggle_wr;
  logic [WIDTH-1:0] cfg_int_en;
  logic cfg_int_en_wr;
  logic [WIDTH-1:0] cfg_rise_en;
  logic cfg_rise_en_wr;
  logic [WIDTH-1:0] cfg_fall_en;
  logic cfg_fall_en_wr;
  logic [WIDTH-1:0] cfg_int_status;
  logic cfg_int_status_wr;
  logic [WIDTH-1:0] sts_int_status_set;

  modport regs (output cfg_out, cfg_out_wr, cfg_dir, cfg_dir_wr, cfg_set, cfg_set_wr, cfg_clear, cfg_clear_wr,
    cfg_toggle, cfg_toggle_wr, cfg_int_en, cfg_int_en_wr, cfg_rise_en, cfg_rise_en_wr, cfg_fall_en,
    cfg_fall_en_wr, cfg_int_status, cfg_int_status_wr, input sts_out, sts_in, sts_int_status_set);
  modport core (output sts_out, sts_in, sts_int_status_set, input cfg_out, cfg_out_wr, cfg_dir, cfg_dir_wr,
    cfg_set, cfg_set_wr, cfg_clear, cfg_clear_wr, cfg_toggle, cfg_toggle_wr, cfg_int_en, cfg_int_en_wr,
    cfg_rise_en, cfg_rise_en_wr, cfg_fall_en, cfg_fall_en_wr, cfg_int_status, cfg_int_status_wr);
  modport monitor (input cfg_out, cfg_out_wr, cfg_dir, cfg_dir_wr, cfg_set, cfg_set_wr, cfg_clear,
    cfg_clear_wr, cfg_toggle, cfg_toggle_wr, cfg_int_en, cfg_int_en_wr, cfg_rise_en, cfg_rise_en_wr,
    cfg_fall_en, cfg_fall_en_wr, cfg_int_status, cfg_int_status_wr, sts_out, sts_in, sts_int_status_set);
endinterface
